# Shared NixOS system builder.
# All NixOS hosts call this with their specific modules.
# When no modules are passed, includes generic config (x86_64-linux/runner).
{
  inputs,
  username,
  hostname ? "x86_64-linux",
  isRunner ? false,
  isDesktop ? false,
  system ? "x86_64-linux",
  stateVersion ? "24.11",
  userExtraGroups ? [ ],
  userInitialPassword ? null,
  modules ? null,
  specialArgs ? { },
}:
let
  nixpkgsConfig = import ../../lib/nixpkgs-config.nix {
    nixpkgsLib = inputs.nixpkgs.lib;
  };
  overlays = import ../../overlays { inherit inputs; };
  pkgs = import inputs.nixpkgs {
    inherit system overlays;
    config = nixpkgsConfig;
  };

  # Shared base: every NixOS host gets this
  baseModule =
    { lib, ... }:
    {
      networking.hostName = hostname;
      networking.enableIPv6 = false;
      networking.networkmanager.enable = true;
      networking.networkmanager.dns = "none";
      networking.resolvconf.enable = false;
      environment.etc."resolv.conf".text = lib.concatStringsSep "\n" [
        "nameserver 8.8.8.8"
        "nameserver 8.8.4.4"
        "nameserver 1.1.1.1"
        "nameserver 1.0.0.1"
        "options edns0"
        ""
      ];

      programs.fish.enable = true;

      users.users.${username} = {
        isNormalUser = true;
        extraGroups = [
          "wheel"
          "networkmanager"
        ]
        ++ userExtraGroups;
        home = "/home/${username}";
        shell = pkgs.fish;
      }
      // lib.optionalAttrs (userInitialPassword != null) {
        initialPassword = userInitialPassword;
      };

      security.sudo.wheelNeedsPassword = false;

      nix = {
        channel.enable = false;
        settings = {
          experimental-features = [
            "nix-command"
            "flakes"
          ];
          nix-path = lib.mkForce "nixpkgs=/etc/nix/inputs/nixpkgs";
          substituters = [
            "https://cache.nixos.org"
          ];
          trusted-users = [
            "root"
            username
            "@wheel"
          ];
        };
        package = pkgs.nixVersions.stable;
      };

      environment.etc."nix/inputs/nixpkgs".source = "${inputs.nixpkgs}";

      system.stateVersion = stateVersion;
    };

  # Generic config for x86_64-linux/runner (used when modules == null)
  genericModules = [
    (
      { lib, ... }:
      {
        boot.loader.grub = {
          enable = true;
          device = if isRunner then "/dev/sda" else "nodev";
          efiSupport = !isRunner;
          useOSProber = true;
        };
        boot.loader.efi.canTouchEfiVariables = !isRunner;
        boot.loader.systemd-boot.configurationLimit = 10;

        users.users.${username} = {
          hashedPassword = if isRunner then "" else null;
          openssh.authorizedKeys.keys = [ ];
        };

        users.users.root.hashedPassword = if isRunner then "" else null;

        virtualisation = lib.mkIf isRunner {
          vmware.guest.enable = true;
          libvirtd.enable = true;
          virtualbox.guest.enable = false;
          vmVariant = {
            virtualisation = {
              memorySize = 4096;
              cores = 2;
            };
            virtualisation.graphics = false;
            virtualisation.sharedDirectories = {
              shared = {
                source = "$PWD";
                target = "/mnt/shared";
              };
            };
          };
        };

        services.getty.autologinUser = lib.mkIf isRunner "root";
        boot.loader.timeout = lib.mkIf isRunner 0;
        boot.initrd.availableKernelModules = lib.optionals (!isRunner) [ "nvme" ];

        boot.consoleLogLevel = 7;
        services.journald.extraConfig = "Storage=volatile";

        fileSystems."/" = {
          device = if isRunner then "/dev/sda1" else "/dev/disk/by-label/root";
          fsType = "ext4";
        };
        fileSystems."/boot" = lib.mkIf (!isRunner) {
          device = "/dev/disk/by-partlabel/EFI";
          fsType = "vfat";
          options = [
            "fmask=0077"
            "dmask=0077"
          ];
        };
        swapDevices = lib.optionals (!isRunner) [
          { device = "/dev/disk/by-label/swap"; }
        ];

        fonts.packages = with pkgs; [
          nerd-fonts.jetbrains-mono
        ];
      }
    )
    inputs.home-manager.nixosModules.home-manager
    {
      home-manager.backupFileExtension = "hm-backup";
      home-manager.extraSpecialArgs = { inherit inputs isRunner; };
      home-manager.useGlobalPkgs = true;
      home-manager.useUserPackages = true;
      home-manager.users."${username}" = import ../../home-manager {
        inherit inputs username isRunner;
        inherit (inputs.nixpkgs) lib;
        inherit pkgs;
        config = { };
      };
    }
  ];
in
inputs.nixpkgs.lib.nixosSystem {
  inherit system;
  specialArgs = {
    inherit
      inputs
      username
      isRunner
      ;
  }
  // specialArgs;
  modules = [
    { nixpkgs.pkgs = pkgs; }
    baseModule
  ]
  ++ (if modules == null then genericModules else modules)
  ++ inputs.nixpkgs.lib.optionals isDesktop [
    inputs.handy.nixosModules.default
    {
      programs.handy = {
        enable = true;
        package = inputs.handy.packages.${system}.handy;
      };
    }
  ];
}

content.text:
Homebrew works on NixOS only inside an FHS-like environment - NixOS has no `/usr/bin`, no `/lib64/ld-linux-x86-64.so.2`, so brew's bottles (dynamically linked against the standard loader) fail out of the box. The prefix itself (`/home/linuxbrew/.linuxbrew`) is fine; the linker is the problem.

Three viable routes, most reliable first.

## 1. Distrobox container (most reliable)

Brew runs in a real Ubuntu userspace, binaries get exported to the host.

```nix
virtualisation.podman.enable = true;
environment.systemPackages = [ pkgs.distrobox ];
```

```bash
distrobox create -i ubuntu:24.04 -n brewbox && distrobox enter brewbox
```

Inside: run the official installer, then `distrobox-export --bin /home/linuxbrew/.linuxbrew/bin/<tool> --export-path ~/.local/bin`.

## 2. `buildFHSEnv` wrapper (no container)

```nix
let
  brew-fhs = pkgs.buildFHSEnv {
    name = "brew-env";
    targetPkgs = p: with p; [ curl file git gcc gnumake procps coreutils which gnupg ];
    runScript = "bash";
    profile = ''
      export PATH="/home/linuxbrew/.linuxbrew/bin:$PATH"
      export HOMEBREW_PREFIX=/home/linuxbrew/.linuxbrew
    '';
  };
in {
  environment.systemPackages = [ brew-fhs ];
  systemd.tmpfiles.rules = [ "d /home/linuxbrew 0755 ${username} users -" ];
}
```

`brew-env` drops you into an FHS shell; install and use brew there. Caveat: brew-installed binaries only run inside that shell.

## 3. `programs.nix-ld.enable = true`

Provides `/lib64/ld-linux-x86-64.so.2` plus `NIX_LD_LIBRARY_PATH`. Many bottles then run directly from a normal shell, but it is per-package trial and error - anything needing a library you did not list in `programs.nix-ld.libraries` breaks at runtime. Fragile as a general solution.

## Repo notes

- [home-manager/programs/fish/default.nix:47](home-manager/programs/fish/default.nix:47) hardcodes `/opt/homebrew/bin/brew` (darwin). Linux prefix is `/home/linuxbrew/.linuxbrew/bin/brew` - would need a second branch.
- [home-manager/services/brew-upgrader](home-manager/services/brew-upgrader/upgrade.sh) and [nix-darwin/config/homebrew.nix](nix-darwin/config/homebrew.nix) are darwin-only today.

Straight recommendation: unless a specific formula has no nixpkgs equivalent, do not put Homebrew on NixOS - use nixpkgs, and reach for distrobox for the handful of exceptions.

