{
  inputs,
  username,
  ...
}:
import ../../hosts/nixos {
  inherit inputs username;
  hostname = "matic";
  isDesktop = true;
  userExtraGroups = [
    "input"
    "video"
    "audio"
    "docker"
    "keyd"
  ];
  modules = [
    # Framework 13" AMD AI 300 hardware support
    inputs.nixos-hardware.nixosModules.framework-amd-ai-300-series

    # Hardware configuration
    ./hardware-configuration.nix

    # Shared keyd config and application mapper wiring
    ../../config/keyd/default.nix

    # System configuration
    (
      {
        config,
        lib,
        pkgs,
        ...
      }:
      {
        # Boot loader (EFI/systemd-boot)
        boot.loader.systemd-boot.enable = true;
        boot.loader.systemd-boot.configurationLimit = 10;
        boot.loader.efi.canTouchEfiVariables = true;
        boot.loader.grub.enable = false;
        boot.loader.timeout = 3;

        # TPM2 auto-unlock for LUKS disk encryption
        boot.initrd.systemd.enable = true;
        boot.initrd.luks.devices."luks-eb20879c-a48d-4334-99a4-bf77a3ad289a".crypttabExtraOpts = [
          "tpm2-device=auto"
        ];

        # Filesystem hardening
        boot.kernel.sysctl = {
          "fs.protected_regular" = 2;
          "fs.protected_fifos" = 2;
          "fs.protected_symlinks" = 1;
          "fs.protected_hardlinks" = 1;
        };

        # AMD power management kernel params
        boot.kernelParams = [
          "amdgpu.abmlevel=3" # auto backlight management
          "amdgpu.runpm=1" # runtime power management for GPU
          "amd_pstate=active" # AMD P-state driver (better than acpi-cpufreq)
          "amdgpu.dcdebugmask=0x410" # disable PSR and REPLAY to fix screen flickering
        ];

        # Networking
        networking.networkmanager.wifi = {
          powersave = true;
          scanRandMacAddress = true;
          macAddress = "stable-ssid";
        };

        networking.firewall = {
          enable = true;
          trustedInterfaces = [ "tailscale0" ];
          allowedTCPPorts = [ ];
          allowedUDPPorts = [ ];
          logRefusedConnections = true;
        };

        # extraSetFlags is used instead of extraUpFlags because the latter only
        # applies when authKeyFile is set; `tailscale set` is applied on every boot.
        services.tailscale = {
          enable = true;
          useRoutingFeatures = "both";
          extraSetFlags = [
            "--accept-dns=true"
            "--advertise-exit-node"
            "--ssh"
          ];
        };

        # Audit logging
        security.auditd.enable = true;
        security.audit = {
          enable = true;
          rules = [
            "-a exit,always -F arch=b64 -S execve -k exec"
            "-a exit,always -F arch=b32 -S execve -k exec"
            "-a exit,always -F arch=b64 -S setuid,setgid,setresuid,setresgid -k priv_esc"
            "-w /etc/sudoers -p wa -k sudoers"
            "-w /etc/passwd -p wa -k identity"
            "-w /etc/shadow -p wa -k identity"
            "-w /etc/ssh -p wa -k ssh"
          ];
        };

        # Docker
        virtualisation.docker.enable = true;

        # Home Manager activation can take a long time (npm globals, cargo installs, etc.)
        systemd.services."home-manager-${username}".serviceConfig.TimeoutStartSec = lib.mkForce "30m";

        # Immutable root - prevents rm -rf / by blocking top-level entry removal
        systemd.services.immutable-root = {
          description = "Set immutable flag on /";
          wantedBy = [ "multi-user.target" ];
          serviceConfig = {
            Type = "oneshot";
            RemainAfterExit = true;
            ExecStart = "${pkgs.e2fsprogs}/bin/chattr +i /";

