{
  programs.zsh = {
    enable = true;
    dotDir = "${config.xdg.configHome}/zsh";
    enableCompletion = true;
    autocd = true;
    autosuggestion.enable = true;
    syntaxHighlighting.enable = true;
    historySubstringSearch.enable = true;

    history = {
      size = -1;
      save = -1;
      path = "$HOME/.zsh_history";
      ignoreDups = true;
      share = true;
      extended = true;
    };

    # envExtra goes to .zshenv (always sourced)
    envExtra = ''
      # Load Homebrew environment
      if [ -f /opt/homebrew/bin/brew ]; then
          eval "$(/opt/homebrew/bin/brew shellenv)"
      fi

      # Local binaries must be available to non-interactive zsh commands too.
      export PATH="$HOME/.bun/install/global/node_modules/.bin:$HOME/.bun/bin:$HOME/.cargo/bin:$HOME/.local/bin:$PATH"

      # Set XDG_RUNTIME_DIR on Linux for consistent socket paths (e.g., zellij)
      if [ "$(uname)" = "Linux" ]; then
          export XDG_RUNTIME_DIR="/run/user/$(id -u)"

          # OpenSSL for cargo builds (rust crates like openssl-sys)
          export PKG_CONFIG_PATH="${pkgs.openssl.dev}/lib/pkgconfig''${PKG_CONFIG_PATH:+:$PKG_CONFIG_PATH}"
          export OPENSSL_DIR="${pkgs.openssl.dev}"
          export OPENSSL_LIB_DIR="${pkgs.openssl.out}/lib"
          export OPENSSL_INCLUDE_DIR="${pkgs.openssl.dev}/include"

          # ICU for CGo builds (e.g. go-icu-regex used by beads)
          export PKG_CONFIG_PATH="${pkgs.icu.dev}/lib/pkgconfig''${PKG_CONFIG_PATH:+:$PKG_CONFIG_PATH}"
          export CGO_CFLAGS="-I${pkgs.icu.dev}/include''${CGO_CFLAGS:+ $CGO_CFLAGS}"
          export CGO_CXXFLAGS="-I${pkgs.icu.dev}/include''${CGO_CXXFLAGS:+ $CGO_CXXFLAGS}"
          export CGO_LDFLAGS="-L${pkgs.icu.out}/lib''${CGO_LDFLAGS:+ $CGO_LDFLAGS}"

          # Native libraries for bun-installed packages (e.g. @oh-my-pi/pi-natives, sharp, keytar)
          export LD_LIBRARY_PATH="${lib.optionalString pkgs.stdenv.isLinux "${pkgs.alsa-lib}/lib:"}${pkgs.glib.out}/lib:${pkgs.libsecret}/lib:${pkgs.nspr}/lib:${pkgs.nss}/lib:${pkgs.stdenv.cc.cc.lib}/lib:${pkgs.zlib}/lib''${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"
      fi

      # Define aliases in .zshenv so non-interactive zsh invocations can use them.
      alias copy='clipboard-copy'
      alias paste='clipboard-paste'
      alias rm='${if pkgs.stdenv.isDarwin then "trash" else "gomi"}'
    '';

    initContent = ''
      # Go configuration
      export GOPATH="$HOME/go"

      # Last line = highest priority (each export prepends, so last ends up at front of PATH)
      export PATH="$PATH:$HOME/go/bin"
      export PATH="/nix/var/nix/profiles/default/bin:$PATH"
      export PATH="$HOME/.nix-profile/bin:$PATH"
      export PATH="$HOME/.local/bin:$PATH"
      export PATH="$HOME/.cargo/bin:$PATH"
      export PATH="$HOME/.local/scripts:$PATH"
      export PATH="$HOME/.bun/bin:$PATH"
      export PATH="/opt/homebrew/opt/postgresql@18/bin:$PATH"
      export PATH="/opt/homebrew/bin:$PATH"
      export PATH="$HOME/.bun/install/global/node_modules/.bin:$PATH"

      # FNM (Fast Node Manager) configuration
      ${
        if pkgs.stdenv.isDarwin then
          ''export FNM_DIR="$HOME/Library/Application Support/fnm"''
        else
          ''export FNM_DIR="$HOME/.local/share/fnm"''
      }
      export FNM_COREPACK_ENABLED="false"
      ${
        if pkgs.stdenv.hostPlatform.isAarch64 then
          ''export FNM_ARCH="arm64"''
        else
          ''export FNM_ARCH="x64"''
      }
      export FNM_RESOLVE_ENGINES="false"
      export FNM_LOGLEVEL="info"
      export FNM_NODE_DIST_MIRROR="https://nodejs.org/dist"
      export FNM_VERSION_FILE_STRATEGY="local"

      # Worktrunk shell init
      if command -v wt >/dev/null 2>&1; then
        eval "$(wt config shell init zsh)"
      fi
    '';
  };
}

