{
  home.packages = with pkgs; [
    bash-language-server
  ];

  home.file.".bash_env".source = ./bash_env.sh;

  home.sessionVariables = {
    BASH_ENV = "$HOME/.bash_env";
  };

  programs.bash = {
    enable = true;
    enableCompletion = true;

    historySize = -1;
    historyFileSize = -1;
    historyControl = [
      "ignoredups"
      "ignorespace"
    ];
    historyIgnore = [
      "ls"
      "cd"
      "exit"
